import ast,base64,copy,hashlib,json
D=json.loads(base64.b64decode(''))
checks=[]
def check(name,condition):
 if not condition: raise AssertionError(name)
 checks.append(name)
b=ast.parse(D['base']);c=ast.parse(D['candidate']);bad=ast.parse(D['invalid_draft'])
compile(c,'<same-root-pureformat>','exec')
check('candidate_ast_compile_only',True)
def assignment(tree,name):
 return next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets)).value
expected=ast.literal_eval(assignment(c,'EXPECTED'))
try:
 ast.literal_eval(assignment(bad,'EXPECTED'))
except ValueError:
 check('unfrozen_json_null_draft_rejected',True)
else:
 raise AssertionError('invalid draft unexpectedly literal')
for name in ['remain','sha','read_pin','write_new','sync_dir']:
 bo=next(n for n in b.body if isinstance(n,ast.FunctionDef) and n.name==name)
 co=next(n for n in c.body if isinstance(n,ast.FunctionDef) and n.name==name)
 check('helper_'+name+'_exact_source',ast.get_source_segment(D['base'],bo)==ast.get_source_segment(D['candidate'],co))
check('FORMAT_CONFIG_exact',ast.literal_eval(assignment(c,'FORMAT_CONFIG')).decode()==D['config'])
check('FORMAT_CONFIG_SHA_exact',ast.literal_eval(assignment(c,'FORMAT_CONFIG_SHA'))==hashlib.sha256(D['config'].encode()).hexdigest())
inputs=D['input_pins']
check('four_fixed_input_names',set(inputs)==set(expected) and len(expected)==4)
for name,identity in inputs.items():
 check('candidate_admitted_sha_'+name,identity['sha256']==expected[name][1])
check('stdin_original_262144_cap',D['stdin_bytes']<=262144)
check('whole50',ast.literal_eval(assignment(c,'LIMIT'))==50.0)
check('tool_same',ast.dump(assignment(b,'FMT'))==ast.dump(assignment(c,'FMT')) and ast.dump(assignment(b,'FMT_SHA'))==ast.dump(assignment(c,'FMT_SHA')))
base_loop=next(n for n in ast.walk(b) if isinstance(n,ast.For) and isinstance(n.target,ast.Name) and n.target.id=='name')
new_loop=next(n for n in ast.walk(c) if isinstance(n,ast.For) and isinstance(n.target,ast.Name) and n.target.id=='name')
bo=next(n for n in base_loop.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='argv' for t in n.targets))
co=next(n for n in new_loop.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='argv' for t in n.targets))
check('new_argv_only_owned_config',ast.unparse(co.value)=="[str(FMT), '--config-path', str(ROOT / 'rustfmt.toml'), '--edition', '2024', '--emit', 'stdout']")
new_loop=copy.deepcopy(new_loop)
co=next(n for n in new_loop.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='argv' for t in n.targets))
co.value=copy.deepcopy(bo.value)
check('all_child_custody_and_caps_exact_except_config_argv',ast.dump(base_loop)==ast.dump(new_loop))
print(json.dumps({'schema':'heptabao.same-root-formatter-ast-checks.v1','checks':checks,'count':len(checks),'passed':True,'modules_executed':0,'host_operations':0,'rust_invocations':0,'source_sha256':hashlib.sha256(D['candidate'].encode()).hexdigest()},sort_keys=True))
